/// setter (always for stage -1, as the manager calls them). The bias is its `f32` bits.
enum class EeGeTexStage : uint32_t {
  AlphaMode = 1,
  ColorMode,
  MagFilterMode,
  MinFilterMode,
  MipFilterMode,
  MipMapBias,
  TextureAddressingMode,
};

/// A model as `GEModel::StoreLoaded` takes it.
struct EeGeCemModel;

/// The bitmap.
struct EeGeBitmap;

/// The font bitmap.
struct EeGeFontBitmap;

/// The model.
struct EeGeModel;

/// The model manager.
struct EeGeModelManager;

/// The terrain mesh.
struct EeGeTerrainMesh;

/// The texture.
struct EeGeTexture;

/// The texture manager.
struct EeGeTextureManager;

/// The host: `owner` is the C++ bitmap of the object calling.
using EeGeBmpHostFn = ptrdiff_t(*)(void *owner, EeGeBmpOp op, void *obj, ptrdiff_t a, ptrdiff_t b);

/// `GERectangle` (sizeof 0x10), in the C++'s member order.
struct EeGeRectangle {
  float bottom;
  float left;
  float right;
  float top;
};

/// Four out (or in) pointers in vertex order: top left, top right, then the original's third and fourth.
using EeGeBmpQuad = void*[4];

/// `GE2DPoint` (sizeof 8).
struct EeGe2DPoint {
  float x;
  float y;
};

/// The host: `owner` is the C++ font bitmap of the object calling.
using EeGeFbHostFn = ptrdiff_t(*)(void *owner, EeGeFbOp op, void *obj, ptrdiff_t a, ptrdiff_t b);

/// Receives one point of an interpolation (`std::vector::push_back` on the C++ side).
using EeGePush2D = void(*)(void *context, const EeGe2DPoint *point);

/// `GE3DPoint` (sizeof 0xc).
struct EeGe3DPoint {
  float x;
  float y;
  float z;
};

/// Receives one point of a 3D interpolation.
using EeGePush3D = void(*)(void *context, const EeGe3DPoint *point);

/// `GEVector` (sizeof 0xc).
struct EeGeVector {
  float x;
  float y;
  float z;
};

/// `GE3DLine` (sizeof 0x18): start, direction.
struct EeGe3DLine {
  EeGe3DPoint start;
  EeGeVector direction;
};

/// `GE3DPlane` (sizeof 0x18): a point on the plane, the normal.
struct EeGe3DPlane {
  EeGe3DPoint point;
  EeGeVector normal;
};

/// `GETransformation` (sizeof 0x40): row-major 4x4, the translation in column 3.
struct EeGeTransformation {
  float m[4][4];
};

/// `GEOrientation` (sizeof 0xc).
struct EeGeOrientation {
  float yaw;
  float pitch;
  float roll;
};

/// `GEQuaternion` (sizeof 0x10).
struct EeGeQuaternion {
  float x;
  float y;
  float z;
  float w;
};

/// `GEBoundingBox` (sizeof 0x24): the two corners, then width (x), height (z) and depth (y).
struct EeGeBoundingBox {
  EeGe3DPoint bottom_left_front;
  EeGe3DPoint top_right_back;
  float width;
  float height;
  float depth;
};

/// Receives one rectangle of a split.
using EeGePushRectangle = void(*)(void *context, const EeGeRectangle *rectangle);

/// `GETerrainMesh::GETMPointRow` and `GETMTileRow`: the first map column, the count, the items.
struct EeGeTmRow {
  unsigned long start;
  unsigned long count;
  const uint8_t *items;
};

/// What the queries read of a `GETerrainMesh`: its rows and its four map-edge planes (`mFrontPlane`, `mBackPlane`,
/// `mLeftPlane`, `mRightPlane`, contiguous in the class).
struct EeGeTerrainView {
  const EeGeTmRow *point_rows;
  const EeGeTmRow *tile_rows;
  unsigned long tile_row_count;
  const EeGe3DPlane *planes;
};

/// The platform's text functions and the font's measure (`PlatUtf8Decode`, `PlatMbsNInc`, `PlatCp1252ByteOf`,
/// `PlatFontMeasure`).
struct EeGeTextOps {
  uint32_t (*decode)(const char *text, uint32_t *out_length);
  uint8_t *(*next_chars)(const uint8_t *text, size_t characters);
  int (*cp1252_byte_of)(uint32_t character);
  int32_t (*measure)(const void *font, const char *text, uint32_t length);
};

/// The C++ host: `owner` is the C++ manager the object belongs to.
using EeGeManHostFn = ptrdiff_t(*)(void *owner,
                                   EeGeManOp op,
                                   void *obj,
                                   ptrdiff_t a,
                                   ptrdiff_t b,
                                   ptrdiff_t c);

/// The host: `owner` is the C++ model of the object calling.
using EeGeModHostFn = ptrdiff_t(*)(void *owner,
                                   EeGeModOp op,
                                   void *obj,
                                   ptrdiff_t a,
                                   ptrdiff_t b,
                                   ptrdiff_t c);

/// One entry of the shared frames map (`std::map<unsigned long, long>`: frame, offset to the frame it shares).
struct EeGeSharedFrame {
  uint32_t frame;
  int32_t offset;
};

/// A material's ranges at one LOD: `GetVertexStartingIndex()`, `GetPolygonStartingIndex(lod)`,
/// `GetPolygonRangeLength(lod)`.
struct EeGePhysicalMaterial {
  unsigned long vertex_start;
  unsigned long polygon_start;
  unsigned long polygon_length;
};

/// The callback table over `GEModel*` handles (`const GEModel*` as `*const c_void`).
struct EeGePhysicalModels {
  bool (*has_parent)(const void *model);
  void (*internal_transform)(const void *model, unsigned long frame, EeGeTransformation *out);
  void (*center)(const void *model, EeGe3DPoint *out);
  float (*radius)(const void *model, unsigned long frame);
  void (*bbox)(const void *model, unsigned long frame, EeGeBoundingBox *out);
  unsigned long (*material_count)(const void *model);
  void (*material)(const void *model,
                   unsigned long index,
                   unsigned long lod,
                   EeGePhysicalMaterial *out);
  void (*triangle)(const void *model,
                   unsigned long frame,
                   unsigned long lod,
                   unsigned long polygon,
                   unsigned long vertex_start,
                   EeGe3DPoint *out);
  unsigned long (*sub_model_count)(const void *model);
  const void *(*sub_model)(const void *model, unsigned long index);
  unsigned long (*lod_count)(const void *model);
  unsigned long (*polygon_count)(const void *model, unsigned long lod);
  /// `GEPhysicalModel theModel(model, location, scale); theModel.SetFrame(frame);
  /// theModel.Intersects(line, lod, distance, true)`.
  bool (*retry_line)(const void *model,
                     const EeGeTransformation *location,
                     unsigned long frame,
                     float scale,
                     const EeGe3DLine *line,
                     unsigned long lod);
};

/// `GETextureDescription` (lle/GETextureManager.h), field for field.
struct EeGeTextureDescription {
  unsigned long surface_volatility;
  unsigned long frame_format;
  unsigned long pixel_depth;
  long num_mip_levels_to_drop;
  bool is_3d_renderable;
  bool is_transparency_enabled;
  bool has_alpha;
  bool create_mipmaps;
  bool use_texture_pack;
};

/// The host: `owner` is the C++ texture of the object calling.
using EeGeTexHostFn = ptrdiff_t(*)(void *owner,
                                   EeGeTexOp op,
                                   void *obj,
                                   ptrdiff_t a,
                                   ptrdiff_t b,
                                   ptrdiff_t c);

/// `GESurfaceDescription` (lle/GESurface.h), field for field.
struct EeGeSurfaceDescription {
  /// `mType`.
  unsigned long kind;
  unsigned long pixel_format;
  unsigned long surface_volatility;
  unsigned long width;
  unsigned long height;
  unsigned long m14;
  long mip_level_count;
  unsigned long pixel_depth;
  bool is_3d_renderable;
  bool is_transparency_enabled;
  /// The constructor's one store (false).
  bool no_alpha;
};

/// `GETStage` (lle/GETexture.h), field for field.
struct EeGeTStage {
  /// `mTexture` (`GETexture*`).
  void *texture;
  unsigned long color_mode;
  unsigned long alpha_mode;
  unsigned long texture_addressing_mode;
  unsigned long min_filter_mode;
  unsigned long mag_filter_mode;
  unsigned long mip_filter_mode;
  float mip_map_bias;
};

/// `GETextureCoordinate`: u, v.
struct EeGeTexCoord {
  float u;
  float v;
};

/// The surface a frame is stored into (`GEStoreFrame`): depth 16 or 32, format, no alpha, pixel size, row pitch.
struct EeGeStoreTarget {
  unsigned long pixel_depth;
  unsigned long pixel_format;
  bool no_alpha;
  unsigned long pixel_width;
  unsigned long pixel_height;
  unsigned long bytes_per_row;
};

/// The host: `owner` is the C++ terrain mesh of the object calling.
using EeGeTmHostFn = ptrdiff_t(*)(void *owner, EeGeTmOp op, void *obj, ptrdiff_t a, ptrdiff_t b);

/// `GETerrainMesh::GETMPoint`: height, quantized normal (a pointer into the quantized-vector table), colour index.
struct EeGeTmPoint {
  float z;
  const EeGeVector *normal;
  uint8_t color_table_index;
};

/// `GETerrainMesh::GETMTile` (sizeof 4).
struct EeGeTmTile {
  uint16_t reference_count;
  uint8_t texture_set_id;
  uint8_t water_info;
};

/// `GEViewport` (sizeof 0x288), in the C++'s member order.
struct EeGeViewport {
  EeGeRectangle orthographic_rectangle;
  EeGeRectangle view_rectangle;
  EeGe3DPlane front_plane;
  EeGe3DPlane rear_plane;
  EeGe3DPlane left_plane;
  EeGe3DPlane right_plane;
  EeGe3DPlane top_plane;
  EeGe3DPlane bottom_plane;
  EeGeTransformation camera;
  EeGeTransformation camera_inverse;
  EeGeTransformation orthographic_denormalization;
  EeGeTransformation perspective_denormalization;
  EeGeTransformation orthographic_projection;
  EeGeTransformation perspective_projection;
  EeGeVector camera_look_at_vector;
  float orthographic_scale;
  float orthographic_depth_scale;
  float orthographic_depth_offset;
  float perspective_scale;
  float perspective_depth_scale;
  float perspective_depth_offset;
  float aspect_ratio;
  float aspect_ratio_multiplier;
  float field_of_view;
  float field_of_view_multiplier;
  float front_clipping_distance;
  float half_height;
  float half_width;
  float rear_clipping_distance;
  float x_center;
  float y_center;
  float y_clipping_plane;
  float near_depth;
  float far_depth;
};

/// The typed reads and writes of one `FSFile` (`FSFile::Read(T&)`, `FSFile::Write(const T&)`).
struct EeGeFieldIo {
  void *file;
  long (*read_u8)(void *file, uint8_t *out);
  long (*read_u16)(void *file, uint16_t *out);
  long (*read_u32)(void *file, uint32_t *out);
  long (*read_f32)(void *file, float *out);
  long (*write_u8)(void *file, uint8_t value);
  long (*write_u16)(void *file, uint16_t value);
  long (*write_u32)(void *file, uint32_t value);
  long (*write_f32)(void *file, float value);
  /// `Read(char*, length, read)`.
  long (*read_bytes)(void *file, uint8_t *out, uint32_t length, uint32_t *read);
  /// `Write(const char*, length, written)`.
  long (*write_bytes)(void *file, const uint8_t *data, uint32_t length, uint32_t *written);
  /// `FSFileSpec::GetPosition` (a plain `FSFile` has none: `kErrorFailed`).
  long (*get_position)(void *file, long *out);
  /// `FSFileSpec::SetPosition(offset, kFileOriginBegin, false)`.
  long (*set_position)(void *file, long offset);
};

/// `GETerrainMesh::GETMRenderVertex` (sizeof 0x28 on the original's 32 bits): the rasterizer fills the point and
/// colour; the mesh writes the fog of war's visibility and, for a cliff vertex, the terrain visibility it copies.
struct EeGeTmRenderVertex {
  EeGe3DPoint point;
  float color[3];
  float visibility;
  float fog;
  unsigned long clip_flags;
  float *linked_visibility;
};

/// `GETerrainMesh::GETMPolygon`: a visible triangle.
struct EeGeTmPolygon {
  EeGeTmRenderVertex *vertices[3];
  float alpha[3];
  float uv[3][2];
};

/// `GETerrainMesh::GETMMaterialView`: a material of the frame as the renderer reads it.
struct EeGeTmMaterialView {
  void *texture;
  EeGeTmPolygon **polygons;
  size_t polygon_count;
  EeGeTmPolygon **indices;
  size_t indices_length;
  EeGeTmPolygon **strips;
  size_t strips_length;
};

/// `GETexture::Load`'s arguments but the texture and the screen (`EeGeManOp::TexLoad`'s `a`).
struct EeGeTexLoad {
  /// The decoded file (`const EeOfTexture*`).
  void *file;
  /// The description `Load` reads and writes.
  EeGeSurfaceDescription *description;
  bool create_mipmaps;
  long num_mip_levels_to_drop;
  unsigned long frame_format;
};

/// A rectangle as GERectangle's setters fill it: left, top, right, bottom.
using EeGeTexRect = float[4];

/// A copy between two surfaces (`EeGeTexOp::SurfCopyTo` / `SurfCopyWithFilter`'s `b`).
struct EeGeTexCopy {
  EeGeTexRect source;
  EeGeTexRect destination;
  /// `CopyTo`'s `inTransparent` (always false here).
  bool transparent;
};

